    private val repository: StockAnalysisRepository,
    savedStateHandle: SavedStateHandle
) : ViewModel() {

    private val symbol: String = checkNotNull(savedStateHandle[ARG_SYMBOL]) {
        "StockDetailViewModel requires a non-null \"$ARG_SYMBOL\" nav argument"
